import{_ as e,o as a,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"产品定义与边界","description":"Hearth 的一句话定位、它是什么与不是什么、首选用户、明确不承诺的范围与体验承诺。","frontmatter":{"title":"产品定义与边界","description":"Hearth 的一句话定位、它是什么与不是什么、首选用户、明确不承诺的范围与体验承诺。","outline":[2,3]},"headers":[],"relativePath":"product/definition.md","filePath":"product/definition.md","lastUpdated":1793706118000}'),r={name:"product/definition.md"};function o(d,t,n,s,h,c){return a(),i("div",null,[...t[0]||(t[0]=[l('<p class="eyebrow">PRODUCT DEFINITION</p><h1 id="产品定义与边界" tabindex="-1">产品定义与边界 <a class="header-anchor" href="#产品定义与边界" aria-label="Permalink to &quot;产品定义与边界&quot;">​</a></h1><p class="lead">Hearth 为谁做、解决什么问题、明确不承诺什么。先钉住边界，再讨论架构和实现。</p><h2 id="一句话定位" tabindex="-1">一句话定位 <a class="header-anchor" href="#一句话定位" aria-label="Permalink to &quot;一句话定位&quot;">​</a></h2><blockquote><p><strong>Hearth 是一个拥有个人上下文、持久执行、真实工具和多设备入口的通用个人 Agent OS；它把人从重复的数字劳动中解放出来，而不是制造另一个需要看管的聊天窗口。</strong></p></blockquote><p>它是单用户、自托管、长期驻留、低打扰、低 Token 的个人 Agent OS。产品名是 Hearth，仓库建议为 <code>hearth-os</code>，命令行为 <code>hearth</code>，常驻服务为 <code>hearthd</code>，包命名空间为 <code>@hearth/*</code>。</p><h2 id="它是什么-不是什么" tabindex="-1">它是什么，不是什么 <a class="header-anchor" href="#它是什么-不是什么" aria-label="Permalink to &quot;它是什么，不是什么&quot;">​</a></h2><p>Hearth 不是：</p><ul><li>另一个 Coding Agent；</li><li>一个只会转发提示词的 Codex 套壳；</li><li>一个把所有权限交给模型的黑盒自动化；</li><li>一个只在聊天框里回答问题的助手；</li><li>一个企业多租户 Agent 平台；</li><li>一个需要用户每天维护提示词、插件和工作流的工具。</li></ul><p>Hearth 是：</p><ul><li><strong>Control Plane</strong>：决定做什么、是否允许、何时打扰、如何恢复；</li><li><strong>Durable Harness</strong>：把意图变成可恢复、可审计、可回执的执行；</li><li><strong>并列 Executor 集合</strong>：Native、Codex、Connector、Browser、GUI、Document/Data、Human；</li><li><strong>Memory OS</strong>：让人物、项目、偏好、承诺和经验可被安全召回；</li><li><strong>Evolution OS</strong>：让重复成功沉淀成技能，但变化必须经过评估和回滚；</li><li><strong>Experience Plane</strong>：用任务卡、审批和产物承载交互，而不是无穷聊天记录。</li></ul><h2 id="首选用户" tabindex="-1">首选用户 <a class="header-anchor" href="#首选用户" aria-label="Permalink to &quot;首选用户&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>假设</th></tr></thead><tbody><tr><td>用户</td><td>1 个主要用户，可能有 1–3 个可信协作者</td></tr><tr><td>设备</td><td>一台主力电脑、一台常驻机器、一部手机</td></tr><tr><td>工作</td><td>研究、写作、文档、邮件、日程、代码、Issue、PR、数据和网页操作混合</td></tr><tr><td>技术能力</td><td>能运行本地服务，但不希望每天维护 Agent 配置</td></tr><tr><td>隐私要求</td><td>个人文件和凭据不能默认上传到不可信第三方</td></tr><tr><td>使用方式</td><td>主动任务、定时任务、通知触发和手动发起并存</td></tr></tbody></table><p>第一版不追求“所有人都能用”，而追求“一个真实用户愿意每天用”。</p><h2 id="明确不承诺" tabindex="-1">明确不承诺 <a class="header-anchor" href="#明确不承诺" aria-label="Permalink to &quot;明确不承诺&quot;">​</a></h2><ul><li>物理世界机器人操作；</li><li>代替用户承担法律、医疗、金融等专业责任；</li><li>未审批的付款、签约、删除、公开发布或权限变更；</li><li>对任意软件 100% 无人值守；</li><li>企业 IAM、多租户、组织审计和计费；</li><li>第一天覆盖全部八类任务；</li><li>与底层模型厂商比模型能力；</li><li>通过无限自主循环制造“像人”的假象。</li></ul><h2 id="体验承诺" tabindex="-1">体验承诺 <a class="header-anchor" href="#体验承诺" aria-label="Permalink to &quot;体验承诺&quot;">​</a></h2><ul><li>用户一眼知道 Agent 正在做什么；</li><li>需要人时只出现一个明确动作；</li><li>不需要理解 Worker、Harness、Token 等内部术语；</li><li>手机可以完成查看、审批、接管和发起；</li><li>任何失败都能看到原因和恢复选项；</li><li>通知是可预期的；</li><li>从第一个可运行增量开始，用户就能通过真实界面完成任务，而不是只能在 CLI、日志或测试里看到能力。</li></ul>',18)])])}const g=e(r,[["render",o]]);export{p as __pageData,g as default};
